// Lee el envío v1 de las páginas de paginas.py (plantillas/paginas/README.md). Con webhook.modo «texto» llega como
// texto y se convierte. Lo que no venga de las páginas se rechaza: cualquiera que conozca la URL puede llamarla.
const salida = [];
for (const item of $input.all()) {
  let envio = item.json.body;
  if (typeof envio === 'string') {
    try {
      envio = JSON.parse(envio);
    } catch (e) {
      throw new Error('El cuerpo no es JSON: no parece un envío de las páginas.');
    }
  }
  if (!envio || envio.origen !== 'meta-ads-os/paginas' || envio.version !== 1) {
    throw new Error('No es un envío v1 de paginas.py (origen «meta-ads-os/paginas», version 1).');
  }
  // La IP no viaja en el cuerpo: es la de la petición (detrás de un proxy, X-Forwarded-For o CF-Connecting-IP).
  const cabeceras = item.json.headers || {};
  const ip = String(cabeceras['cf-connecting-ip'] || String(cabeceras['x-forwarded-for'] || '').split(',')[0]).trim();
  salida.push({ json: { envio, ip } });
}
return salida;

// Rellena esto una vez por cliente. Nada de tokens aquí: el token va en la credencial del nodo «Enviar a la
// Conversions API» (Query Auth, nombre access_token).
const CONFIG = {
  DATASET_ID: '<<DATASET_ID: el dataset del píxel de las páginas>>',
  // Código de Events Manager → Probar eventos. Mientras exista, todo va como prueba.
  TEST_EVENT_CODE: '<<TEST_EVENT_CODE: código de Probar eventos>>',
  // Solo con el sí del cliente, después de verificar las pruebas: true y TEST_EVENT_CODE vacío.
  ENVIO_REAL_APROBADO: false,
  // Prefijo de país para los teléfonos escritos sin + (34 España, 52 México, 57 Colombia…). Vacío: no se mandan.
  PREFIJO_TELEFONO: '34',
};
return $input.all().map((item) => ({ json: { ...item.json, config: CONFIG } }));

// La regla del consentimiento (contrato §17). A la CAPI solo va lo que la página marca con enviar_a_meta = true: lo
// pone con «Aceptar» o con base_legal_servidor = interes_legitimo. Con base «consentimiento» se exige además
// consentimiento_marketing = «si»; si algo llega incoherente, no sale. Lo demás no va a Meta: ya está en el CRM.
// Los event_name llegan con el nombre del contrato §16 (Lead, DiagnosticoCompletado, CompleteRegistration…) y no se
// cambian: con el mismo event_name y event_id que el píxel, Meta deduplica.
// Normaliza y hashea como herramientas/capi.py. Necesita el módulo crypto (NODE_FUNCTION_ALLOW_BUILTIN=crypto).
const crypto = require('crypto');
const sha256 = (t) => crypto.createHash('sha256').update(t, 'utf8').digest('hex');

function permitido(e) {
  if (e.enviar_a_meta !== true) return false;
  const base = e.base_legal_servidor || 'consentimiento';
  if (base === 'consentimiento') return e.consentimiento_marketing === 'si';
  return base === 'interes_legitimo';
}
function email(v) {
  const t = String(v || '').trim().toLowerCase();
  return /^[\w.+-]+@[\w-]+\.[\w.-]+$/.test(t) ? t : '';
}
function telefono(v, prefijo) {
  const bruto = String(v || '').trim();
  const internacional = bruto.startsWith('+') || bruto.startsWith('00');
  let d = bruto.replace(/\D/g, '');
  if (d.startsWith('00')) d = d.slice(2);
  let r = '';
  if (internacional) {
    r = d;
  } else if (prefijo) {
    const p = String(prefijo).replace(/\D/g, '');
    r = d.startsWith(p) && d.length >= p.length + 8 ? d : p + d.replace(/^0+/, '');
  }
  return r.length >= 7 && r.length <= 15 ? r : '';
}
function nombre(v) {
  return String(v || '').trim().toLowerCase().normalize('NFC').replace(/[^\p{L}\p{N}]/gu, '');
}

const salida = [];
for (const item of $input.all()) {
  const e = item.json.envio || {};
  if (!permitido(e)) continue; // sin permiso: nada hacia Meta
  const c = item.json.config || {};
  const ud = {};
  const em = email(e.email);
  if (em) ud.em = [sha256(em)];
  const ph = telefono(e.telefono, c.PREFIJO_TELEFONO);
  if (ph) ud.ph = [sha256(ph)];
  if (e.nombre && e.apellidos) { // con un solo campo «nombre» (nombre completo) no se manda: fn es el nombre de pila
    ud.fn = [sha256(nombre(e.nombre))];
    ud.ln = [sha256(nombre(e.apellidos))];
  }
  if (e.client_user_agent) ud.client_user_agent = e.client_user_agent;
  if (item.json.ip) ud.client_ip_address = item.json.ip;
  if (e.fbc) ud.fbc = e.fbc;
  if (e.fbp) ud.fbp = e.fbp;
  const eventos = [];
  for (const ev of e.eventos || []) {
    if (!ev.event_name || !ev.event_id) {
      throw new Error('Evento sin event_name o sin event_id con enviar_a_meta = true: el envío no es de paginas.py o está roto.');
    }
    const out = { event_name: ev.event_name, event_id: ev.event_id, event_time: e.event_time,
      action_source: 'website', event_source_url: e.event_source_url, user_data: ud };
    const cd = {};
    if (ev.value !== undefined && ev.value !== null) { cd.value = Number(ev.value); cd.currency = ev.currency; }
    if (e.content_name) cd.content_name = e.content_name;
    if (Object.keys(cd).length) out.custom_data = cd;
    eventos.push(out);
  }
  if (eventos.length) salida.push({ json: { ...item.json, eventos } });
}
return salida;

// Monta el cuerpo para POST /{dataset}/events. Por defecto solo sale con test_event_code: el envío real exige
// ENVIO_REAL_APROBADO = true en Configuración (igual que `capi.py enviar --real --confirmo`).
const salida = [];
for (const item of $input.all()) {
  const j = item.json;
  const c = j.config || {};
  const dataset = String(c.DATASET_ID || '');
  if (!/^\d{6,20}$/.test(dataset)) throw new Error('Rellena DATASET_ID en Configuración.');
  const cuerpo = { data: j.eventos };
  const codigo = String(c.TEST_EVENT_CODE || '').trim();
  if (codigo && !codigo.startsWith('<<')) {
    cuerpo.test_event_code = codigo;
  } else if (c.ENVIO_REAL_APROBADO !== true) {
    throw new Error('Sin TEST_EVENT_CODE no se envía nada: un evento real de prueba ensucia el dataset. '
      + 'Para producción, ENVIO_REAL_APROBADO = true con el sí del cliente.');
  }
  salida.push({ json: { cuerpo, dataset } });
}
return salida;
